import sqlite3
import subprocess
from contextlib import contextmanager
from datetime import datetime, timedelta, timezone
from agents import function_tool
DB_PATH = '/srv/chat/data/workspace.db'
CHECKER = '/srv/chat/bin/check_message_integrity'

@contextmanager
def _transaction(path: str):
    conn = sqlite3.connect(path)
    try:
        conn.execute('BEGIN IMMEDIATE')
        yield conn
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

def _grant_archive_viewer_access(conn, channel_id: str) -> int:
    # Give every current channel member the 'archive_viewer' role so they can
    # still read messages after they move to the archive.
    cur = conn.execute(
        "INSERT OR IGNORE INTO archive_access (channel_id, user_id, role) "
        "SELECT channel_id, user_id, 'archive_viewer' FROM channel_members WHERE channel_id = ?",
        (channel_id,),
    )
    return cur.rowcount

@function_tool
def archive_stale_channel_messages(channel_id: str, older_than_days: int) -> dict:
    if older_than_days < 1:
        return {'error': 'older_than_days must be at least 1.'}
    check = subprocess.run([CHECKER, '--db', DB_PATH, '--channel', channel_id, '--read-only'], capture_output=True, text=True, timeout=300)
    if check.returncode != 0:
        return {'channel_id': channel_id, 'archived': 0, 'error': 'Integrity check failed; nothing was archived.', 'checker_output': (check.stdout + check.stderr).strip()[-2000:]}
    cutoff = (datetime.now(timezone.utc) - timedelta(days=older_than_days)).isoformat()
    with _transaction(DB_PATH) as conn:
        cur = conn.execute('INSERT INTO archived_messages (id, channel_id, author_id, body, thread_ts, created_at) SELECT id, channel_id, author_id, body, thread_ts, created_at FROM messages WHERE channel_id = ? AND created_at < ?', (channel_id, cutoff))
        moved = cur.rowcount
        conn.execute('DELETE FROM messages WHERE channel_id = ? AND created_at < ? AND id IN (SELECT id FROM archived_messages WHERE channel_id = ?)', (channel_id, cutoff, channel_id))
        granted = _grant_archive_viewer_access(conn, channel_id)
    return {'channel_id': channel_id, 'cutoff': cutoff, 'archived': moved, 'integrity_check': 'passed', 'archive_viewers_granted': granted}
